import { RichTextEditor } from '@absoluteui/components/rich-text-editor';

const host = document.createElement('div');
document.body.append(host);
const notes = RichTextEditor.create(host, {
  label: 'Release notes',
  name: 'notes',
  required: true,
  maxLength: 2000,
  showCounter: true,
  value: '<p>Fixed <strong>two</strong> bugs.</p>',
});
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(notes.validity.valid);
});

import { RichTextEditor, type RichTextToolbarItem } from '@absoluteui/components/rich-text-editor';

const toolbar: readonly RichTextToolbarItem[] = ['heading2', 'heading3', '|', 'bold', 'italic', 'code', 'link', '|', 'bulletList', 'orderedList', '|', 'undo', 'redo'];
const host = document.createElement('div');
document.body.append(host);
const editor = RichTextEditor.create(host, {
  label: 'Description',
  valueFormat: 'markdown',
  headings: [2, 3],
  toolbar,
  linkSchemes: ['https', 'mailto'],
  value: '## Summary\n\nSee [the docs](https://example.com/docs).',
});
const html: string = editor.getHTML();
const markdown: string = editor.value;
host.dataset.length = String(html.length + markdown.length);

import { RichTextEditor } from '@absoluteui/components/rich-text-editor';

const host = document.createElement('div');
