import { RichTextEditor } from '@absoluteui/components/rich-text-editor';
import { Button } from '@absoluteui/components/button';

const host = document.createElement('div');
const bold = document.createElement('button');
bold.type = 'button';
bold.textContent = 'Bold';
Button.enhance(bold, { size: 'sm' });
document.body.append(bold, host);
const editor = RichTextEditor.create(host, { label: 'Comment', toolbar: ['undo', 'redo'] });
// Keep the editor's selection when the button is pressed with the mouse.
bold.addEventListener('mousedown', (e) => {
  e.preventDefault();
});
bold.addEventListener('click', () => {
  editor.command('bold');
  bold.setAttribute('aria-pressed', String(editor.formatState.marks.includes('bold')));
});

import { richTextFromMarkdown, richTextToHtml } from '@absoluteui/components/rich-text-editor';

const httpsOnly = (url: string): string | null => (url.startsWith('https://') ? url : null);
const doc = richTextFromMarkdown('# Notes\n\n- **one**\n- [two](https://example.com)', httpsOnly);
const html: string = richTextToHtml(doc);
document.body.dataset.preview = html;
